#!/usr/bin/env python3
"""Build the generated files of the docs site.

    python3 tools/repo/site/build.py            regenerate every output in place
    python3 tools/repo/site/build.py --check    exit 1 if a committed output is stale

Outputs. All are deterministic: inputs are read in sorted order and nothing
records the time of the build.

    site/evals/index.html   the eval dashboard, one self-contained HTML file
    site/llms.txt           an index of the docs pages, in the llms.txt convention
    site/llms-full.txt      every docs page, concatenated in reading order
    README.md               only the block between the proof markers

Inputs.

    site/_config.yml        title, description, url, baseurl (single-line values)
    site/**/*.md            docs pages; front matter needs title, description, nav_order
    packs/*/evals/results/**/summary.json   redacted eval summaries, also under
    labs/*/evals/results/**/summary.json    packs/*/skills/*/evals/results/**,
    engine/evals/results/**/summary.json    labs/*/skills/*/evals/results/** (the
                                            engine's skills are listed as pack "engine")

A redacted summary is a `claude plugin eval` result with model identifiers,
paths and transcripts removed. The reader takes the fields it knows and ignores
every other field, so new fields never break the build:

    schemaVersion
    aggregates.overallScore, casesPassed, casesTotal, meanDelta (or top level)
    cases[].name, cases[].score, cases[].delta (or under cases[].aggregates)
    costUsd, durationSeconds, claudeVersion
    the run date: date, startedAt, or a YYYY-MM-DD results folder name
    optional: cases[].skill, cases[].scoreWithout, cases[].arms.with,
              cases[].runsPerCase, suite.threshold, suite.modelPinned,
              partial, partialReason

tools/repo/skills/CONTRACT.md defines the format and the stable rule; this
reader applies the same rule. Runs come from the length of cases[].arms.with
(the runs that happened), else cases[].runsPerCase. A bare "runs" count is
ignored, because the eval summary table counts both arms there.

When a case has no skill field, it is matched to the skill folder whose name
prefixes the case name (packs/<pack>/skills/<skill>/SKILL.md), or to the
pack's only skill.

Exit codes: 0 done or up to date, 1 stale outputs (--check), 2 bad input or usage.

Standard library only, Python 3.9 or later. No network access.
"""

import argparse
import datetime
import html
import json
import math
import posixpath
import re
import sys
from dataclasses import dataclass
from pathlib import Path
from typing import Any, Callable, Dict, List, Optional, Sequence, Tuple

SCRIPT = Path(__file__).resolve()
DEFAULT_ROOT = SCRIPT.parents[3]
CSS_FILE = SCRIPT.with_name("dashboard.css")
BUILD_CMD = "python3 tools/repo/site/build.py"

# The stable rule. A skill is stable at or above all three.
STABLE_MIN_SCORE = 0.80
STABLE_MIN_DELTA = 0.20
STABLE_MIN_RUNS = 3
STABLE_MIN_CASES = 3
# Absorbs float noise from averaging, such as (0.7 + 0.8 + 0.9) / 3 < 0.8.
EPSILON = 1e-9

CONFIG = "site/_config.yml"
DASHBOARD = "site/evals/index.html"
LLMS = "site/llms.txt"
LLMS_FULL = "site/llms-full.txt"
README = "README.md"

PROOF_START = (
    "<!-- proof:start (generated by tools/repo/site/build.py from the committed "
    "eval summaries; edit those, not this block) -->"
)
PROOF_END = "<!-- proof:end -->"
PROOF_BLOCK = re.compile(r"<!-- proof:start\b.*?-->.*?<!-- proof:end -->", re.DOTALL)

SUMMARY_PATTERNS = (
    "engine/evals/results/**/summary.json",
    "packs/*/evals/results/**/summary.json",
    "labs/*/evals/results/**/summary.json",
    "packs/*/skills/*/evals/results/**/summary.json",
    "labs/*/skills/*/evals/results/**/summary.json",
)

# Keys that appear only in raw, unredacted results, where they carry model
# identifiers or transcripts. The build warns about them; the dashboard never
# renders them either way.
RAW_ONLY_KEYS = frozenset(
    {
        "model",
        "modelOverride",
        "judgeModel",
        "judgeVotes",
        "promptMarkdown",
        "graderMarkdown",
        "tracePath",
        "evidence",
    }
)

# A summary's own run date wins; otherwise the date comes from a timestamp,
# such as the startedAt that `claude plugin eval` writes.
DATE_KEYS = ("date", "runDate")
TIMESTAMP_KEYS = ("startedAt", "started_at", "timestamp", "createdAt", "generatedAt")

DASHBOARD_SUMMARY = (
    "Each measured skill's with-skill score, Δ against a no-skill baseline, runs "
    "and date, built from redacted eval summaries."
)

STABLE = "stable"
BELOW = "below"
REGRESSION = "regression"
NO_BASELINE = "no-baseline"
IMPROVED = "improved"

# status -> (css class, icon, label). Icons are decorative; the label carries
# the meaning, so status never depends on color alone.
STATUS_META = {
    STABLE: ("status-stable", "✓", "Meets the stable bar"),
    BELOW: ("status-below", "!", "Below the stable bar"),
    REGRESSION: ("status-regression", "▼", "Regression"),
    NO_BASELINE: ("status-none", "–", "No baseline"),
}
CASE_META = {
    IMPROVED: ("status-improved", "▲", "Improved"),
    REGRESSION: ("status-regression", "▼", "Regression"),
    NO_BASELINE: ("status-none", "–", "No baseline"),
}
KIND_ORDER = {"pack": 0, "lab": 1}
#: The engine plugin's folder; its eval summaries are listed as this pack.
ENGINE_PACK = "engine"


class InputError(Exception):
    """Bad input: a malformed summary, page or config file. Exit code 2."""


@dataclass
class SiteConfig:
    title: str
    description: str
    url: str
    baseurl: str
    lang: str

    @property
    def base(self) -> str:
        """The absolute site root ending in '/', or '' when no url is set."""
        if not self.url:
            return ""
        base = self.url.rstrip("/")
        path = self.baseurl.strip("/")
        if path:
            base += "/" + path
        return base + "/"


@dataclass
class Page:
    path: str  # relative to site/, posix
    title: str
    description: str
    nav_order: int
    url: str  # relative to the site root
    body: str


@dataclass
class Case:
    name: str
    score: float
    delta: Optional[float]
    runs: Optional[int]
    skill: Optional[str]
    score_without: Optional[float] = None
    anchor: str = ""


@dataclass
class Run:
    path: str  # repo-relative posix path, or the bare file name if outside the repo
    kind: str  # "pack" or "lab"
    pack: str
    date: Optional[str]  # YYYY-MM-DD
    stamp: str  # sortable timestamp text
    overall_score: Optional[float]
    mean_delta: Optional[float]
    cases_passed: Optional[int]
    cases_total: Optional[int]
    threshold: Optional[float]
    cost_usd: Optional[float]
    duration_seconds: Optional[float]
    claude_version: Optional[str]
    partial: bool
    partial_reason: Optional[str]
    sample: bool
    cases: List[Case]
    model_pinned: Optional[bool] = None

    def sort_key(self) -> Tuple[str, str, str]:
        return (self.date or "", self.stamp, self.path)

    @property
    def runs(self) -> Optional[int]:
        counts = [case.runs for case in self.cases]
        if counts and all(count is not None for count in counts):
            return min(count for count in counts if count is not None)
        return None


@dataclass
class SkillRow:
    kind: str
    pack: str
    skill: Optional[str]  # None groups cases that match no skill folder
    run: Run
    cases: List[Case]
    score: float
    delta: Optional[float]
    runs: Optional[int]
    status: str
    reasons: List[str]
    anchor: str = ""


# ---------------------------------------------------------------- formatting


def fmt_score(value: float) -> str:
    return "{:.2f}".format(value)


def fmt_delta(value: float) -> str:
    text = "{:+.2f}".format(value)
    return "0.00" if text in ("+0.00", "-0.00") else text


def fmt_cost(value: float) -> str:
    return "${:,.2f}".format(value)


def fmt_duration(seconds: float) -> str:
    total = int(round(seconds))
    if total < 60:
        return "{} s".format(total)
    minutes, secs = divmod(total, 60)
    if minutes < 60:
        return "{} min {} s".format(minutes, secs)
    hours, minutes = divmod(minutes, 60)
    return "{} h {} min".format(hours, minutes)


def _fmt_under(value: float, bar: float, fmt: Callable[[float], str]) -> str:
    """Format a value that is under a bar without letting rounding hide it."""
    text = fmt(value)
    if float(text) >= bar - EPSILON:
        text = "{:+.3f}".format(value) if fmt is fmt_delta else "{:.3f}".format(value)
    return text


def _pct(value: float) -> str:
    text = "{:.1f}".format(max(0.0, min(100.0, value)))
    return text.rstrip("0").rstrip(".")


def _mean(values: Sequence[float]) -> float:
    return sum(values) / len(values)


def _plural(count: int, word: str, plural: str = "") -> str:
    return "{} {}".format(count, word if count == 1 else (plural or word + "s"))


def _show(value: Any) -> str:
    text = json.dumps(value, ensure_ascii=False)
    return text if len(text) <= 60 else text[:57] + "..."


def _slug(text: str) -> str:
    return re.sub(r"[^a-z0-9]+", "-", text.lower()).strip("-") or "item"


class _Anchors:
    """Hands out unique HTML ids."""

    def __init__(self) -> None:
        self.used = set()  # type: set

    def take(self, base: str) -> str:
        anchor, number = base, 2
        while anchor in self.used:
            anchor = "{}-{}".format(base, number)
            number += 1
        self.used.add(anchor)
        return anchor


# ---------------------------------------------------- config and docs pages

_KEY_LINE = re.compile(r"^([A-Za-z_][A-Za-z0-9_-]*):(?:[ \t]+(.*?))?[ \t]*$")
_DOUBLE_QUOTED = re.compile(r'^"((?:[^"\\]|\\.)*)"(?:[ \t]+#.*)?$')
_SINGLE_QUOTED = re.compile(r"^'((?:[^']|'')*)'(?:[ \t]+#.*)?$")
_FRONT_MATTER = re.compile(r"\A---[ \t]*\n(.*?\n)?---[ \t]*(?:\n|\Z)", re.DOTALL)


def _scalar(value: str, where: str) -> str:
    """Parse one YAML scalar from the small subset this tool supports."""
    value = value.strip()
    if not value:
        return ""
    match = _DOUBLE_QUOTED.match(value)
    if match:
        try:
            return json.loads('"' + match.group(1) + '"')
        except ValueError:
            raise InputError("{}: unsupported escape in a double-quoted value".format(where))
    match = _SINGLE_QUOTED.match(value)
    if match:
        return match.group(1).replace("''", "'")
    if value[0] in "\"'":
        raise InputError("{}: unterminated quoted value".format(where))
    if value[0] in "[{>|*&!%@`":
        raise InputError("{}: unsupported YAML; use a plain or quoted single-line value".format(where))
    value = re.split(r"[ \t]#", value, maxsplit=1)[0].rstrip()
    if ": " in value or value.endswith(":"):
        raise InputError("{}: quote values that contain ': '".format(where))
    return value


def parse_simple_yaml(text: str, where: str, keys: Optional[Sequence[str]] = None, first_line: int = 1) -> Dict[str, str]:
    """Read top-level `key: value` scalars; indented blocks and list items are skipped.

    With `keys`, only those keys are parsed and every other line is ignored.
    """
    values = {}  # type: Dict[str, str]
    for offset, raw in enumerate(text.splitlines()):
        line_where = "{}:{}".format(where, first_line + offset)
        stripped = raw.strip()
        if not stripped or stripped.startswith("#") or raw[0] in " \t" or raw.startswith("- "):
            continue
        match = _KEY_LINE.match(raw)
        if not match:
            if keys is None:
                raise InputError("{}: cannot parse {}".format(line_where, _show(raw)))
            continue
        key = match.group(1)
        if keys is not None and key not in keys:
            continue
        if key in values:
            raise InputError("{}: duplicate key {}".format(line_where, key))
        values[key] = _scalar(match.group(2) or "", line_where)
    return values


def load_config(root: Path) -> SiteConfig:
    path = root / CONFIG
    try:
        text = path.read_text(encoding="utf-8")
    except FileNotFoundError:
        raise InputError("{} not found".format(CONFIG))
    values = parse_simple_yaml(text, CONFIG, keys=("title", "description", "url", "baseurl", "lang"))
    title = values.get("title", "")
    if not title:
        raise InputError("{}: title is required".format(CONFIG))
    return SiteConfig(
        title=title,
        description=values.get("description", ""),
        url=values.get("url", ""),
        baseurl=values.get("baseurl", ""),
        lang=values.get("lang", "") or "en",
    )


def split_front_matter(text: str, where: str) -> Tuple[Dict[str, str], str]:
    text = text.replace("\r\n", "\n")
    if text.startswith("﻿"):
        text = text[1:]
    match = _FRONT_MATTER.match(text)
    if not match:
        raise InputError("{}: missing front matter (title, description, nav_order)".format(where))
    meta = parse_simple_yaml(match.group(1) or "", where, first_line=2)
    return meta, text[match.end() :]


def load_pages(root: Path) -> List[Page]:
    site = root / "site"
    if not site.is_dir():
        raise InputError("site/ not found")
    pages = []
    for path in sorted(site.rglob("*.md"), key=lambda p: p.relative_to(site).as_posix()):
        rel = path.relative_to(site)
        if any(part.startswith(("_", ".")) for part in rel.parts) or rel.parts[0] in ("vendor", "node_modules"):
            continue  # Jekyll doesn't publish these
        where = "site/" + rel.as_posix()
        meta, body = split_front_matter(path.read_text(encoding="utf-8"), where)
        for key in ("title", "description", "nav_order"):
            if not meta.get(key):
                raise InputError("{}: front matter needs {}".format(where, key))
        try:
            nav_order = int(meta["nav_order"])
        except ValueError:
            raise InputError("{}: nav_order must be a whole number".format(where))
        permalink = meta.get("permalink", "")
        url = (permalink.lstrip("/") or "index.html") if permalink else rel.with_suffix(".html").as_posix()
        pages.append(
            Page(
                path=rel.as_posix(),
                title=meta["title"],
                description=meta["description"],
                nav_order=nav_order,
                url=url,
                body=body.strip("\n") + "\n",
            )
        )
    if not pages:
        raise InputError("site/ has no docs pages")
    pages.sort(key=lambda page: (page.nav_order, page.path))
    return pages


# ------------------------------------------------------------ eval summaries


def find_summaries(root: Path) -> List[Path]:
    found = {}  # type: Dict[str, Path]
    for pattern in SUMMARY_PATTERNS:
        for path in root.glob(pattern):
            if path.is_file():
                found[path.relative_to(root).as_posix()] = path
    return [found[key] for key in sorted(found)]


_MISSING = object()


def _lookup(data: Dict[str, Any], *dotted: str) -> Tuple[Optional[str], Any]:
    """Return (key, value) for the first dotted path present and not null."""
    for key in dotted:
        node = data  # type: Any
        for part in key.split("."):
            if isinstance(node, dict) and part in node:
                node = node[part]
            else:
                node = _MISSING
                break
        if node is not _MISSING and node is not None:
            return key, node
    return None, None


def _as_number(value: Any, where: str, low: Optional[float] = None, high: Optional[float] = None) -> float:
    if isinstance(value, bool) or not isinstance(value, (int, float)) or not math.isfinite(value):
        raise InputError("{}: expected a number, got {}".format(where, _show(value)))
    number = float(value)
    if (low is not None and number < low - EPSILON) or (high is not None and number > high + EPSILON):
        bounds = "{} to {}".format(low, high) if high is not None else "at least {}".format(low)
        raise InputError("{}: {} is outside {}".format(where, _show(value), bounds))
    return number


def _as_count(value: Any, where: str, minimum: int = 0) -> int:
    if (
        isinstance(value, bool)
        or not isinstance(value, (int, float))
        or not math.isfinite(value)
        or value != int(value)
    ):
        raise InputError("{}: expected a whole number, got {}".format(where, _show(value)))
    if int(value) < minimum:
        raise InputError("{}: expected at least {}, got {}".format(where, minimum, _show(value)))
    return int(value)


def _opt_number(data: Dict[str, Any], keys: Sequence[str], where: str, low: Optional[float], high: Optional[float]) -> Optional[float]:
    key, value = _lookup(data, *keys)
    return None if key is None else _as_number(value, "{}: {}".format(where, key), low, high)


def _opt_count(data: Dict[str, Any], keys: Sequence[str], where: str) -> Optional[int]:
    key, value = _lookup(data, *keys)
    return None if key is None else _as_count(value, "{}: {}".format(where, key))


def _opt_runs(data: Dict[str, Any], keys: Sequence[str], where: str) -> Optional[int]:
    key, value = _lookup(data, *keys)
    if key is None:
        return None
    if isinstance(value, list):
        return len(value) or None
    return _as_count(value, "{}: {}".format(where, key), minimum=1)


def _opt_text(data: Dict[str, Any], keys: Sequence[str], where: str) -> Optional[str]:
    key, value = _lookup(data, *keys)
    if key is None:
        return None
    if not isinstance(value, str):
        raise InputError("{}: {}: expected a string, got {}".format(where, key, _show(value)))
    return value.strip() or None


_DATE_IN_TEXT = re.compile(r"(\d{4})-(\d{2})-(\d{2})")


def _date_in(text: str) -> Optional[str]:
    match = _DATE_IN_TEXT.search(text)
    if not match:
        return None
    try:
        datetime.date(int(match.group(1)), int(match.group(2)), int(match.group(3)))
    except ValueError:
        return None
    return match.group(0)


def _moment(value: Any, key: str, where: str) -> Tuple[str, str]:
    """(YYYY-MM-DD, sortable stamp) from an ISO string or an epoch number."""
    if isinstance(value, str):
        date = _date_in(value)
        if date is None:
            raise InputError("{}: {}: no YYYY-MM-DD date in {}".format(where, key, _show(value)))
        return date, value.strip()
    if isinstance(value, (int, float)) and not isinstance(value, bool) and math.isfinite(value):
        seconds = value / 1000.0 if value > 1e11 else float(value)
        try:
            moment = datetime.datetime.fromtimestamp(seconds, tz=datetime.timezone.utc)
        except (OverflowError, OSError, ValueError):
            raise InputError("{}: {}: not a usable timestamp: {}".format(where, key, _show(value)))
        return moment.strftime("%Y-%m-%d"), moment.strftime("%Y-%m-%dT%H:%M:%SZ")
    raise InputError("{}: {}: expected a date string, got {}".format(where, key, _show(value)))


def _run_date(data: Dict[str, Any], parts: Sequence[str], where: str) -> Tuple[Optional[str], str]:
    """The run date and a stamp that orders runs on the same date."""
    date_key, date_value = _lookup(data, *DATE_KEYS)
    stamp_key, stamp_value = _lookup(data, *TIMESTAMP_KEYS)
    stamp_date, stamp = _moment(stamp_value, stamp_key, where) if stamp_key else (None, "")
    if date_key is not None:
        date = _moment(date_value, date_key, where)[0]
        return date, stamp if stamp_date == date else date
    if stamp_date is not None:
        return stamp_date, stamp
    for part in reversed(parts[:-1]):  # the results folder: results/2026-11-05/ or results/<timestamp>/
        date = _date_in(part)
        if date:
            return date, part
    return None, ""


def _raw_keys(node: Any) -> set:
    found = set()
    if isinstance(node, dict):
        for key, value in node.items():
            if key in RAW_ONLY_KEYS:
                found.add(key)
            found |= _raw_keys(value)
    elif isinstance(node, list):
        for item in node:
            found |= _raw_keys(item)
    return found


def _pack_from_data(data: Dict[str, Any]) -> Optional[str]:
    for key in ("pack", "plugin", "pluginId", "suite.pluginId"):
        _, value = _lookup(data, key)
        if isinstance(value, str) and value.strip():
            return value.split("@", 1)[0].strip()
    _, plugins = _lookup(data, "suite.plugins")
    if isinstance(plugins, list) and plugins and isinstance(plugins[0], dict):
        name = plugins[0].get("name")
        if isinstance(name, str) and name.strip():
            return name.strip()
    return None


def _skill_folders(root: Path, kind: str, pack: str) -> List[str]:
    base = root / ("packs" if kind == "pack" else "labs") / pack / "skills"
    if kind == "pack" and pack == ENGINE_PACK and not base.is_dir():
        base = root / ENGINE_PACK / "skills"
    if not base.is_dir():
        return []
    return sorted(child.name for child in base.iterdir() if child.is_dir() and (child / "SKILL.md").is_file())


def attribute_skill(
    case_name: str,
    explicit: Optional[str],
    path_skill: Optional[str],
    run_skill: Optional[str],
    folders: Sequence[str],
) -> Optional[str]:
    """Decide which skill a case measures."""
    for choice in (explicit, path_skill, run_skill):
        if choice:
            return choice
    best = None  # type: Optional[str]
    for folder in folders:
        if case_name == folder or (case_name.startswith(folder) and case_name[len(folder)] in "-_./:"):
            if best is None or len(folder) > len(best):
                best = folder
    if best:
        return best
    return folders[0] if len(folders) == 1 else None


def load_run(path: Path, root: Path, warnings: List[str]) -> Run:
    try:
        parts = path.resolve().relative_to(root.resolve()).parts
        shown = "/".join(parts)
    except ValueError:  # a --summary file outside the repository: never print its absolute path
        parts = (path.name,)
        shown = path.name
    try:
        data = json.loads(path.read_text(encoding="utf-8"))
    except (OSError, UnicodeDecodeError) as exc:
        raise InputError("{}: cannot read: {}".format(shown, exc))
    except ValueError as exc:
        raise InputError("{}: invalid JSON: {}".format(shown, exc))
    if not isinstance(data, dict):
        raise InputError("{}: expected a JSON object".format(shown))

    raw = sorted(_raw_keys(data))
    if raw:
        warnings.append(
            "{}: has keys that only raw results carry ({}); commit redacted summaries only".format(shown, ", ".join(raw))
        )

    kind = pack = path_skill = None  # type: Optional[str]
    if len(parts) >= 4 and parts[0] in ("packs", "labs"):
        kind = "pack" if parts[0] == "packs" else "lab"
        pack = parts[1]
        if len(parts) >= 6 and parts[2] == "skills" and parts[4] == "evals":
            path_skill = parts[3]
    elif len(parts) >= 3 and parts[0] == ENGINE_PACK and parts[1] == "evals":
        kind, pack = "pack", ENGINE_PACK
    if kind is None or pack is None:
        kind, pack = "pack", _pack_from_data(data) or "unknown"
    folders = _skill_folders(root, kind, pack)
    run_skill = _opt_text(data, ("skill",), shown)
    default_runs = _opt_runs(data, ("runsPerCase", "suite.runsPerCase"), shown)

    raw_cases = data.get("cases")
    if raw_cases is None:
        raw_cases = []
    if not isinstance(raw_cases, list):
        raise InputError("{}: cases: expected a list".format(shown))
    cases = []  # type: List[Case]
    names = set()
    for index, item in enumerate(raw_cases):
        where = "{}: cases[{}]".format(shown, index)
        if not isinstance(item, dict):
            raise InputError("{}: expected an object".format(where))
        name = item.get("name")
        if not isinstance(name, str) or not name.strip():
            raise InputError("{}: name: expected a non-empty string".format(where))
        name = name.strip()
        if name in names:
            raise InputError("{}: duplicate case name {}".format(where, _show(name)))
        names.add(name)
        key, score = _lookup(item, "score", "aggregates.score")
        if key is None:
            raise InputError("{} ({}): score is missing".format(where, name))
        _, arm = _lookup(item, "arms.with")
        if isinstance(arm, list) and arm:
            runs = len(arm)  # the runs that happened
        else:
            runs = _opt_runs(item, ("runsPerCase",), where) or default_runs
        cases.append(
            Case(
                name=name,
                score=_as_number(score, "{}: {}".format(where, key), 0.0, 1.0),
                delta=_opt_number(item, ("delta", "aggregates.delta"), where, -1.0, 1.0),
                score_without=_opt_number(item, ("scoreWithout", "aggregates.scoreWithout"), where, 0.0, 1.0),
                runs=runs,
                skill=attribute_skill(name, _opt_text(item, ("skill",), where), path_skill, run_skill, folders),
            )
        )

    key, partial = _lookup(data, "partial")
    if key is not None and not isinstance(partial, bool):
        raise InputError("{}: partial: expected true or false, got {}".format(shown, _show(partial)))
    key, pinned = _lookup(data, "suite.modelPinned", "modelPinned")
    if key is not None and not isinstance(pinned, bool):
        raise InputError("{}: {}: expected true or false, got {}".format(shown, key, _show(pinned)))
    threshold = _opt_number(data, ("threshold", "suite.threshold"), shown, 0.0, 1.0)
    overall = _opt_number(data, ("aggregates.overallScore", "overallScore"), shown, 0.0, 1.0)
    mean_delta = _opt_number(data, ("aggregates.meanDelta", "meanDelta"), shown, -1.0, 1.0)
    passed = _opt_count(data, ("aggregates.casesPassed", "casesPassed"), shown)
    total = _opt_count(data, ("aggregates.casesTotal", "casesTotal"), shown)
    # Fall back to the documented definitions when an aggregate is absent.
    if overall is None and cases:
        overall = _mean([case.score for case in cases])
    deltas = [case.delta for case in cases if case.delta is not None]
    if mean_delta is None and deltas:
        mean_delta = _mean(deltas)
    if total is None:
        total = len(cases)
    if passed is None and threshold is not None:
        passed = sum(1 for case in cases if case.score >= threshold - EPSILON)
    date, stamp = _run_date(data, parts, shown)
    return Run(
        path=shown,
        kind=kind,
        pack=pack,
        date=date,
        stamp=stamp,
        overall_score=overall,
        mean_delta=mean_delta,
        cases_passed=passed,
        cases_total=total,
        threshold=threshold,
        cost_usd=_opt_number(data, ("costUsd",), shown, 0.0, None),
        duration_seconds=_opt_number(data, ("durationSeconds",), shown, 0.0, None),
        claude_version=_opt_text(data, ("claudeVersion",), shown),
        partial=bool(partial),
        partial_reason=_opt_text(data, ("partialReason",), shown),
        sample="_sample" in data,
        cases=cases,
        model_pinned=pinned,
    )


# ------------------------------------------------------------ the stable rule


def classify(
    score: float,
    delta: Optional[float],
    runs: Optional[int],
    partial: bool = False,
    cases: int = STABLE_MIN_CASES,
    delta_cases: Optional[int] = None,
    pinned: Optional[bool] = True,
) -> Tuple[str, List[str]]:
    """Return (status, reasons) for one skill under the stable rule in CONTRACT.md.

    Stable needs a complete two-arm run on a pinned model that covers at least
    3 of the skill's cases, with a Δ for each, a mean score of at least 0.80,
    a mean Δ of at least +0.20, and at least 3 runs per case in each arm.
    """
    if delta is None:
        return NO_BASELINE, ["single-arm run, so there is no Δ"]
    if delta <= EPSILON:
        return REGRESSION, ["worse than no skill" if delta < -EPSILON else "no better than no skill"]
    reasons = []
    if score < STABLE_MIN_SCORE - EPSILON:
        reasons.append(
            "score {} is under {}".format(_fmt_under(score, STABLE_MIN_SCORE, fmt_score), fmt_score(STABLE_MIN_SCORE))
        )
    if delta < STABLE_MIN_DELTA - EPSILON:
        reasons.append(
            "Δ {} is under {}".format(_fmt_under(delta, STABLE_MIN_DELTA, fmt_delta), fmt_delta(STABLE_MIN_DELTA))
        )
    if runs is None:
        reasons.append("runs not recorded")
    elif runs < STABLE_MIN_RUNS:
        reasons.append("{} per arm, needs {}".format(_plural(runs, "run"), STABLE_MIN_RUNS))
    if cases < STABLE_MIN_CASES:
        reasons.append("{}, needs {}".format(_plural(cases, "case"), STABLE_MIN_CASES))
    if delta_cases is not None and delta_cases < cases:
        reasons.append("Δ for {} of {} cases".format(delta_cases, cases))
    if pinned is None:
        reasons.append("model pinning not recorded")
    elif not pinned:
        reasons.append("model not pinned")
    if partial:
        reasons.append("partial run")
    return (BELOW if reasons else STABLE), reasons


def build_skill_rows(runs: Sequence[Run]) -> List[SkillRow]:
    """One row per skill, from that skill's latest complete run."""
    groups = {}  # type: Dict[Tuple[str, str, str], List[Tuple[Run, List[Case]]]]
    for run in runs:
        by_skill = {}  # type: Dict[str, List[Case]]
        for case in run.cases:
            by_skill.setdefault(case.skill or "", []).append(case)
        for skill, cases in by_skill.items():
            groups.setdefault((run.kind, run.pack, skill), []).append((run, cases))
    rows = []
    for (kind, pack, skill), entries in groups.items():
        complete = [entry for entry in entries if not entry[0].partial]
        run, cases = max(complete or entries, key=lambda entry: entry[0].sort_key())
        deltas = [case.delta for case in cases if case.delta is not None]
        counts = [case.runs for case in cases]
        runs_count = min(c for c in counts if c is not None) if all(c is not None for c in counts) else None
        score = _mean([case.score for case in cases])
        delta = _mean(deltas) if deltas else None
        status, reasons = classify(
            score, delta, runs_count, run.partial, len(cases), len(deltas), run.model_pinned
        )
        if deltas and len(deltas) < len(cases) and status != BELOW:
            reasons.append("Δ for {} of {} cases".format(len(deltas), len(cases)))
        if run.partial and status != BELOW:
            reasons.append("partial run")
        rows.append(
            SkillRow(
                kind=kind,
                pack=pack,
                skill=skill or None,
                run=run,
                cases=cases,
                score=score,
                delta=delta,
                runs=runs_count,
                status=status,
                reasons=reasons,
            )
        )
    rows.sort(key=lambda row: (KIND_ORDER.get(row.kind, 9), row.pack, row.skill is None, row.skill or ""))
    anchors = _Anchors()
    for row in rows:
        row.anchor = anchors.take("skill-{}-{}".format(_slug(row.pack), _slug(row.skill or "unattributed")))
    for row in rows:
        for case in row.cases:
            case.anchor = anchors.take("case-{}-{}".format(_slug(row.pack), _slug(case.name)))
    return rows


# ---------------------------------------------------------------- dashboard


def _e(text: Any) -> str:
    return html.escape(str(text), quote=True)


def _badge(meta: Tuple[str, str, str]) -> str:
    css, icon, label = meta
    return '<span class="status {}"><span class="status-icon" aria-hidden="true">{}</span>{}</span>'.format(
        css, icon, _e(label)
    )


def _missing(note: str = "not recorded") -> str:
    return '<span class="muted">—<span class="visually-hidden"> {}</span></span>'.format(_e(note))


def _time(date: Optional[str]) -> str:
    return '<time datetime="{0}">{0}</time>'.format(_e(date)) if date else _missing()


def _meter(score: float) -> str:
    return (
        '<span class="meter" aria-hidden="true"><span class="meter-fill" style="width:{}%"></span>'
        '<span class="mark" style="left:{}%"></span></span>'
    ).format(_pct(score * 100), _pct(STABLE_MIN_SCORE * 100))


def _delta_bar(delta: float) -> str:
    clipped = max(-1.0, min(1.0, delta))
    half = abs(clipped) * 50
    if clipped >= 0:
        fill = '<span class="dbar-fill up" style="left:50%;width:{}%"></span>'.format(_pct(half))
    else:
        fill = '<span class="dbar-fill down" style="left:{}%;width:{}%"></span>'.format(_pct(50 - half), _pct(half))
    return (
        '<span class="dbar" aria-hidden="true"><span class="dbar-zero"></span>{}'
        '<span class="mark" style="left:{}%"></span></span>'
    ).format(fill, _pct(50 + STABLE_MIN_DELTA * 50))


def _score_cell(score: float) -> str:
    return '<td class="num">{}{}</td>'.format(fmt_score(score), _meter(score))


def _delta_cell(delta: Optional[float]) -> str:
    if delta is None:
        return '<td class="num">{}</td>'.format(_missing("no baseline"))
    return '<td class="num">{}{}</td>'.format(_e(fmt_delta(delta)), _delta_bar(delta))


def _count_cell(value: Optional[int]) -> str:
    return '<td class="num">{}</td>'.format(value if value is not None else _missing())


def _pack_label(kind: str, pack: str) -> str:
    return _e(pack) + ('<span class="tag">lab</span>' if kind == "lab" else "")


def _case_status(case: Case) -> str:
    if case.delta is None:
        return NO_BASELINE
    return REGRESSION if case.delta <= EPSILON else IMPROVED


def _table(caption: str, caption_id: str, head: Sequence[Tuple[str, bool]], body_rows: Sequence[str]) -> str:
    cols = "".join(
        '<th scope="col"{}>{}</th>'.format(' class="num"' if numeric else "", label) for label, numeric in head
    )
    return (
        '<div class="table-wrap" role="region" aria-labelledby="{id}" tabindex="0">\n'
        '<table>\n<caption id="{id}">{caption}</caption>\n'
        "<thead><tr>{cols}</tr></thead>\n<tbody>\n{rows}\n</tbody>\n</table>\n</div>"
    ).format(id=caption_id, caption=caption, cols=cols, rows="\n".join(body_rows))


def _tiles(rows: Sequence[SkillRow], runs: Sequence[Run]) -> str:
    packs = sorted({(row.kind, row.pack) for row in rows})
    pack_count = sum(1 for kind, _ in packs if kind == "pack")
    lab_count = len(packs) - pack_count
    where = []
    if pack_count:
        where.append(_plural(pack_count, "pack"))
    if lab_count:
        where.append(_plural(lab_count, "lab"))
    stable = sum(1 for row in rows if row.status == STABLE)
    regressions = sum(1 for row in rows if row.status == REGRESSION)
    deltas = [row.delta for row in rows if row.delta is not None]
    latest = max((run.date for run in runs if run.date), default=None)

    def tile(label: str, value: str, sub: str, alert: bool = False) -> str:
        return '<div class="tile{}"><dt>{}</dt><dd class="value">{}</dd><dd class="sub">{}</dd></div>'.format(
            " is-alert" if alert else "", label, value, sub
        )

    return "\n".join(
        [
            '<dl class="tiles">',
            tile("Skills measured", str(len(rows)), "in " + " and ".join(where)),
            tile(
                "Meet the stable bar",
                "{} of {}".format(stable, len(rows)),
                "score ≥ {}, Δ ≥ {}, {}+ runs".format(
                    fmt_score(STABLE_MIN_SCORE), fmt_delta(STABLE_MIN_DELTA), STABLE_MIN_RUNS
                ),
            ),
            tile("Regressions", str(regressions), "skills with Δ at or below 0", alert=regressions > 0),
            tile(
                "Mean Δ vs no skill",
                _e(fmt_delta(_mean(deltas))) if deltas else _missing("no baseline"),
                "across skills with a baseline",
            ),
            tile("Latest run", _time(latest), _plural(len(runs), "eval summary", "eval summaries")),
            "</dl>",
        ]
    )


def _skills_section(rows: Sequence[SkillRow]) -> str:
    body = []
    for row in rows:
        name = _e(row.skill) if row.skill else '<span class="muted">Unattributed cases</span>'
        reasons = '<span class="reason">{}</span>'.format(_e("; ".join(row.reasons))) if row.reasons else ""
        body.append(
            '<tr id="{}"{}><th scope="row">{}</th><td class="nowrap">{}</td>{}{}{}{}<td>{}</td><td>{}{}</td></tr>'.format(
                row.anchor,
                ' class="is-regression"' if row.status == REGRESSION else "",
                name,
                _pack_label(row.kind, row.pack),
                _score_cell(row.score),
                _delta_cell(row.delta),
                _count_cell(row.runs),
                _count_cell(len(row.cases)),
                _time(row.run.date),
                _badge(STATUS_META[row.status]),
                reasons,
            )
        )
    table = _table(
        "Latest complete run for each skill",
        "skills-caption",
        [
            ("Skill", False),
            ("Pack", False),
            ("Score with skill", True),
            ("Δ vs no skill", True),
            ("Runs", True),
            ("Cases", True),
            ("Date", False),
            ("Against the stable bar", False),
        ],
        body,
    )
    return "\n".join(
        [
            '<section aria-labelledby="skills-heading">',
            '<h2 id="skills-heading">Per skill</h2>',
            '<p class="section-note">A skill\'s score is the mean of its cases\' scores in its latest complete run. '
            "The marks on the bars sit at the stable bar: 0.80 for the score and +0.20 for Δ.</p>",
            table,
            "</section>",
        ]
    )


def _cases_section(rows: Sequence[SkillRow]) -> str:
    groups = []  # type: List[Tuple[Run, List[Tuple[SkillRow, Case]]]]
    for row in rows:
        for run, members in groups:
            if run is row.run:
                members.extend((row, case) for case in row.cases)
                break
        else:
            groups.append((row.run, [(row, case) for case in row.cases]))
    parts = [
        '<section aria-labelledby="cases-heading">',
        '<h2 id="cases-heading">Per case</h2>',
        '<p class="section-note">The cases behind each skill\'s numbers, in the order the suite ran them.</p>',
    ]
    for number, (run, members) in enumerate(groups, 1):
        order = {case.name: index for index, case in enumerate(run.cases)}
        members.sort(key=lambda member: order[member[1].name])
        body = []
        for row, case in members:
            status = _case_status(case)
            reason = ""
            if status == REGRESSION:
                reason = '<span class="reason">{}</span>'.format(
                    "worse than no skill" if (case.delta or 0.0) < -EPSILON else "no better than no skill"
                )
            body.append(
                '<tr id="{}"{}><th scope="row">{}</th><td>{}</td>{}{}{}{}<td>{}{}</td></tr>'.format(
                    case.anchor,
                    ' class="is-regression"' if status == REGRESSION else "",
                    _e(case.name),
                    _e(row.skill) if row.skill else '<span class="muted">Unattributed</span>',
                    _score_cell(case.score),
                    '<td class="num">{}</td>'.format(
                        fmt_score(case.score_without) if case.score_without is not None else _missing("no baseline")
                    ),
                    _delta_cell(case.delta),
                    _count_cell(case.runs),
                    _badge(CASE_META[status]),
                    reason,
                )
            )
        shown = len(members)
        caption = "{} · run of {}{}".format(
            _pack_label(run.kind, run.pack),
            _e(run.date) if run.date else "an unrecorded date",
            "" if shown == len(run.cases) else " · {} of {} cases; the rest have a newer run".format(shown, len(run.cases)),
        )
        parts.append(
            _table(
                caption,
                "cases-caption-{}".format(number),
                [
                    ("Case", False),
                    ("Skill", False),
                    ("With skill", True),
                    ("Without skill", True),
                    ("Δ vs no skill", True),
                    ("Runs", True),
                    ("Result", False),
                ],
                body,
            )
        )
    parts.append("</section>")
    return "\n".join(parts)


def _runs_section(runs: Sequence[Run], rows: Sequence[SkillRow]) -> str:
    used = {id(row.run) for row in rows}
    body = []
    for run in sorted(runs, key=lambda item: item.sort_key(), reverse=True):
        notes = []
        if run.sample:
            notes.append("sample data")
        if run.partial:
            notes.append("partial" + (": " + run.partial_reason.replace("_", " ") if run.partial_reason else ""))
        if id(run) in used:
            notes.append("used above")
        elif run.cases:
            notes.append("superseded by a newer run")
        else:
            notes.append("no cases")
        if run.cases_passed is not None and run.cases_total is not None:
            passed = "{} of {}".format(run.cases_passed, run.cases_total)
            if run.threshold is not None:
                passed += ' <span class="muted">at {}</span>'.format(fmt_score(run.threshold))
        else:
            passed = _missing()
        body.append(
            "<tr><th scope=\"row\">{}</th><td class=\"nowrap\">{}</td><td class=\"num\">{}</td><td class=\"num\">{}</td>"
            "<td class=\"num\">{}</td>{}<td class=\"num\">{}</td><td class=\"num\">{}</td><td>{}</td><td>{}</td></tr>".format(
                _time(run.date),
                _pack_label(run.kind, run.pack),
                fmt_score(run.overall_score) if run.overall_score is not None else _missing(),
                _e(fmt_delta(run.mean_delta)) if run.mean_delta is not None else _missing("no baseline"),
                passed,
                _count_cell(run.runs),
                _e(fmt_cost(run.cost_usd)) if run.cost_usd is not None else _missing(),
                _e(fmt_duration(run.duration_seconds)) if run.duration_seconds is not None else _missing(),
                _e(run.claude_version) if run.claude_version else _missing(),
                _e(", ".join(notes)),
            )
        )
    table = _table(
        "Every committed eval summary, newest first",
        "runs-caption",
        [
            ("Date", False),
            ("Pack", False),
            ("Suite score", True),
            ("Mean Δ", True),
            ("Cases passed", True),
            ("Runs", True),
            ("Cost", True),
            ("Duration", True),
            ("Claude Code", False),
            ("Notes", False),
        ],
        body,
    )
    return "\n".join(
        [
            '<section aria-labelledby="runs-heading">',
            '<h2 id="runs-heading">Runs</h2>',
            '<p class="section-note">Cost is the list-price estimate the eval run reports, judge calls included. '
            "Cases passed counts cases at or above the run's threshold.</p>",
            table,
            "</section>",
        ]
    )


def _regressions_callout(rows: Sequence[SkillRow]) -> str:
    regressions = [row for row in rows if row.status == REGRESSION]
    if not regressions:
        return ""
    items = "\n".join(
        '<li><a href="#{}">{}</a> in {}: Δ {}, {}</li>'.format(
            row.anchor,
            _e(row.skill or "Unattributed cases"),
            _e(row.pack),
            _e(fmt_delta(row.delta if row.delta is not None else 0.0)),
            _e(row.reasons[0]),
        )
        for row in regressions
    )
    return "\n".join(
        [
            '<section class="callout callout-critical" aria-labelledby="attention-heading">',
            '<h2 id="attention-heading">Needs attention</h2>',
            "<p>{} no better than having no skill, so {} rework or retirement.</p>".format(
                "This skill does" if len(regressions) == 1 else "These skills do",
                "it needs" if len(regressions) == 1 else "they need",
            ),
            "<ul>",
            items,
            "</ul>",
            "</section>",
        ]
    )


EMPTY_STATE = """<section class="empty" id="empty-state" aria-labelledby="empty-heading">
<h2 id="empty-heading">No eval results yet</h2>
<p>This page lists each skill's with-skill score and its Δ against a no-skill baseline as soon as a redacted eval summary is committed. Until then it shows nothing, and it never estimates a number.</p>
<ol>
<li>Run a pack's eval cases with and without the pack, writing the raw result outside the repository:
<pre><code>claude plugin eval packs/&lt;pack&gt; --ablation with-without \\
  --output-dir ../eval-results</code></pre></li>
<li>Redact <code>aggregate-result.json</code> into <code>packs/&lt;pack&gt;/evals/results/&lt;date&gt;/summary.json</code> and commit only that file. Raw results hold model identifiers and transcripts.</li>
<li>Rebuild this page:
<pre><code>python3 tools/repo/site/build.py</code></pre></li>
</ol>
<p>The full steps, with cost limits and grader advice, are in <a href="../qualify-a-skill.html">Qualify a skill</a>.</p>
</section>"""

METHOD = """<section aria-labelledby="method-heading">
<h2 id="method-heading">How to read this</h2>
<dl class="defs">
<dt>Score with skill</dt><dd>The mean case score with the skill's plugin loaded, from 0 to 1. A run scores the share of its graders that passed, and a case scores the mean of its runs.</dd>
<dt>Δ vs no skill</dt><dd>The score with the skill minus the score of the same cases run with no plugin loaded. Above 0, the skill helped.</dd>
<dt>Runs</dt><dd>Runs per case in each arm, with and without the skill: the fewest any of the skill's cases got. One run of an agent is noisy, so the stable bar needs at least 3.</dd>
<dt>Stable bar</dt><dd>A score of at least 0.80 and a Δ of at least +0.20, with 3 or more runs per case in each arm, from a complete run on a pinned model that covers at least 3 of the skill's cases, with a Δ for each.</dd>
<dt>Regression</dt><dd>Δ at or below 0: the skill does no better than no skill. It gets reworked or retired, and the result stays published.</dd>
<dt>No baseline</dt><dd>The run had one arm only, so it has no Δ and can't qualify a skill.</dd>
<dt>Partial run</dt><dd>A run that stopped early, for example at its cost ceiling. Each skill uses its latest complete run; a partial run counts only when no complete run exists, and it is flagged.</dd>
<dt>Source</dt><dd>Redacted summaries committed under <code>packs/&lt;pack&gt;/evals/results/</code> and <code>labs/&lt;pack&gt;/evals/results/</code>. Model identifiers, file paths and transcripts are removed before commit.</dd>
</dl>
</section>"""


def render_dashboard(runs: Sequence[Run], rows: Sequence[SkillRow], config: SiteConfig, css: str) -> str:
    """Render the dashboard as one self-contained HTML document."""
    main = []
    if any(run.sample for run in runs):
        main.append(
            '<p class="sample-banner" role="note"><strong>Sample data.</strong> This page was built from a '
            "synthetic fixture. Its numbers are invented and are not eval results.</p>"
        )
    if rows:
        main += [
            '<section aria-labelledby="summary-heading">',
            '<h2 id="summary-heading" class="visually-hidden">Summary</h2>',
            _tiles(rows, runs),
            "</section>",
        ]
        callout = _regressions_callout(rows)
        if callout:
            main.append(callout)
        main += [_skills_section(rows), _cases_section(rows)]
    else:
        main.append(EMPTY_STATE)
    if runs:
        main.append(_runs_section(runs, rows))
    main.append(METHOD)
    count = len(runs)
    return "\n".join(
        [
            "<!doctype html>",
            '<html lang="{}">'.format(_e(config.lang)),
            "<head>",
            '<meta charset="utf-8">',
            '<meta name="viewport" content="width=device-width, initial-scale=1">',
            '<meta name="color-scheme" content="light dark">',
            '<meta name="description" content="{}">'.format(_e(DASHBOARD_SUMMARY)),
            "<title>Eval results · {}</title>".format(_e(config.title)),
            "<!-- Generated by tools/repo/site/build.py from redacted eval summaries. "
            "Do not edit; run python3 tools/repo/site/build.py. -->",
            "<style>",
            css.strip("\n"),
            "</style>",
            "</head>",
            "<body>",
            '<a class="skip-link" href="#main">Skip to results</a>',
            '<div class="wrap">',
            '<header class="page-header">',
            '<nav class="crumbs" aria-label="Breadcrumb"><a href="../index.html">{} docs</a>'
            '<span class="sep" aria-hidden="true">/</span><span aria-current="page">Eval results</span></nav>'.format(
                _e(config.title)
            ),
            "<h1>Skill eval results</h1>",
            '<p class="lede">Each skill runs the same eval cases twice: with the skill loaded and with no skill at all. '
            "The score says how well the cases went with the skill, from 0 to 1. Δ says how much better that is "
            "than no skill. A skill is stable at a score of at least 0.80 and a Δ of at least +0.20 over 3 or "
            "more runs.</p>",
            "</header>",
            '<main id="main">',
            "\n".join(main),
            "</main>",
            '<footer class="page-footer">',
            (
                "<p>Generated by <code>tools/repo/site/build.py</code> from {}. "
                "Every number on this page comes from {}, and nothing is estimated.</p>".format(
                    _plural(count, "eval summary", "eval summaries"), "that file" if count == 1 else "those files"
                )
                if count
                else "<p>Generated by <code>tools/repo/site/build.py</code>. No eval summaries are committed yet.</p>"
            ),
            '<p>How the numbers are made, and how to re-run them: <a href="../qualify-a-skill.html">Qualify a skill</a>.</p>',
            "</footer>",
            "</div>",
            "</body>",
            "</html>",
            "",
        ]
    )


# -------------------------------------------------------- llms.txt and full


def _site_link(base: str, rel: str) -> str:
    return base + rel if base else rel


_INLINE_LINK = re.compile(r"(\]\()([^)\s]+)(\))")
_SCHEME = re.compile(r"^[A-Za-z][A-Za-z0-9+.-]*:")
_FENCE = re.compile(r"^[ ]{0,3}(`{3,}|~{3,})")


def _rewrite_links(page: Page, known: Dict[str, Page], base: str) -> str:
    """Point relative links at published URLs: x.md becomes x.html, as on the site."""
    page_dir = posixpath.dirname(page.path)

    def fix(match: "re.Match") -> str:
        target = match.group(2)
        if target.startswith(("#", "/")) or _SCHEME.match(target):
            return match.group(0)
        path, sep, fragment = target.partition("#")
        resolved = posixpath.normpath(posixpath.join(page_dir, path)) if path else page.path
        if resolved in known:
            resolved = known[resolved].url
        return match.group(1) + _site_link(base, resolved) + sep + fragment + match.group(3)

    lines, fence = [], ""
    for line in page.body.split("\n"):
        opener = _FENCE.match(line)
        if fence:
            if opener and opener.group(1)[0] == fence[0] and len(opener.group(1)) >= len(fence):
                fence = ""
        elif opener:
            fence = opener.group(1)
        else:
            line = _INLINE_LINK.sub(fix, line)
        lines.append(line)
    return "\n".join(lines)


def render_llms(config: SiteConfig, pages: Sequence[Page]) -> str:
    base = config.base
    lines = ["# {}".format(config.title), ""]
    if config.description:
        lines += ["> {}".format(config.description), ""]
    lines += [
        "This file indexes the docs site for agents and tools. Each entry links to a page and says what it covers.",
        "",
        "## Docs",
        "",
    ]
    lines += ["- [{}]({}): {}".format(page.title, _site_link(base, page.url), page.description) for page in pages]
    lines += [
        "",
        "## Eval results",
        "",
        "- [Eval dashboard]({}): {}".format(_site_link(base, "evals/index.html"), DASHBOARD_SUMMARY),
        "",
        "## Optional",
        "",
        "- [Full text]({}): Every docs page above, concatenated in reading order.".format(
            _site_link(base, "llms-full.txt")
        ),
        "",
    ]
    return "\n".join(lines)


def render_llms_full(config: SiteConfig, pages: Sequence[Page]) -> str:
    base = config.base
    known = {page.path: page for page in pages}
    blocks = ["# {}: full text".format(config.title)]
    if config.description:
        blocks.append("> {}".format(config.description))
    blocks.append(
        "Every page of the docs site in reading order, for agents and tools that read a single file. "
        "The page index is [llms.txt]({}).".format(_site_link(base, "llms.txt"))
    )
    for page in pages:
        blocks += ["---", "Source: {}".format(_site_link(base, page.url)), _rewrite_links(page, known, base).strip("\n")]
    return "\n\n".join(blocks) + "\n"


# ------------------------------------------------------------- README block


def _md_cell(text: str) -> str:
    return text.replace("\\", "\\\\").replace("|", "\\|")


def _readme_link(config: SiteConfig, rel: str) -> str:
    return config.base + rel if config.base else "site/" + rel


def render_proof_block(rows: Sequence[SkillRow], config: SiteConfig) -> str:
    dashboard = _readme_link(config, "evals/index.html")
    qualify = "site/qualify-a-skill.md"
    lines = [PROOF_START, ""]
    if not rows:
        lines += [
            "No eval summaries are committed yet, so this section makes no claims. Each skill appears here with its "
            "with-skill score and its Δ against a no-skill baseline once its first redacted eval summary is committed.",
            "",
            "See the [eval dashboard]({}) and [how a skill qualifies]({}).".format(dashboard, qualify),
        ]
    else:
        lines += [
            "| Skill | Pack | With skill | Δ vs no skill | Runs | Date | Against the stable bar |",
            "|---|---|--:|--:|--:|---|---|",
        ]
        for row in rows:
            skill = "[{}]({}#{})".format(_md_cell(row.skill), dashboard, row.anchor) if row.skill else "Unattributed cases"
            status = {
                STABLE: "✓ Meets the stable bar",
                BELOW: "Below the bar",
                REGRESSION: "▼ Regression",
                NO_BASELINE: "No baseline",
            }[row.status]
            if row.reasons:
                status += ": " + "; ".join(row.reasons)
            lines.append(
                "| {} | {} | {} | {} | {} | {} | {} |".format(
                    skill,
                    _md_cell(row.pack + (" (lab)" if row.kind == "lab" else "")),
                    fmt_score(row.score),
                    fmt_delta(row.delta) if row.delta is not None else "—",
                    row.runs if row.runs is not None else "—",
                    row.run.date or "—",
                    _md_cell(status),
                )
            )
        lines += [
            "",
            "Stable means a with-skill score of at least 0.80 and a Δ of at least +0.20, over 3 or more runs on a pinned "
            "model. Every case, run and cost is on the [eval dashboard]({}), and [Qualify a skill]({}) shows how to "
            "re-run the numbers.".format(
                dashboard, qualify
            ),
        ]
    if any(row.run.sample for row in rows):
        lines += ["", "**Sample data:** built from a synthetic fixture. These numbers are invented."]
    lines += ["", PROOF_END]
    return "\n".join(lines)


def render_readme(root: Path, rows: Sequence[SkillRow], config: SiteConfig) -> str:
    try:
        text = (root / README).read_text(encoding="utf-8")
    except FileNotFoundError:
        raise InputError("README.md not found")
    if len(PROOF_BLOCK.findall(text)) != 1:
        raise InputError("README.md needs exactly one block from '<!-- proof:start' to '<!-- proof:end -->'")
    block = render_proof_block(rows, config)
    return PROOF_BLOCK.sub(lambda _match: block, text, count=1)


# ------------------------------------------------------------------ driver


def generate(root: Path, summaries: Optional[Sequence[Path]] = None) -> Tuple[Dict[str, str], List[str]]:
    """Return ({repo-relative path: content}, warnings) for every output."""
    warnings = []  # type: List[str]
    config = load_config(root)
    pages = load_pages(root)
    paths = list(summaries) if summaries is not None else find_summaries(root)
    runs = [load_run(path, root, warnings) for path in paths]
    rows = build_skill_rows(runs)
    try:
        css = CSS_FILE.read_text(encoding="utf-8")
    except OSError as exc:
        raise InputError("cannot read {}: {}".format(CSS_FILE.name, exc))
    outputs = {
        DASHBOARD: render_dashboard(runs, rows, config, css),
        LLMS: render_llms(config, pages),
        LLMS_FULL: render_llms_full(config, pages),
        README: render_readme(root, rows, config),
    }
    return outputs, warnings


def stale_outputs(root: Path, outputs: Dict[str, str]) -> List[str]:
    stale = []
    for rel in sorted(outputs):
        try:
            current = (root / rel).read_text(encoding="utf-8")  # universal newlines: CRLF checkouts compare equal
        except FileNotFoundError:
            stale.append(rel + " (missing)")
            continue
        except (OSError, UnicodeDecodeError) as exc:
            stale.append("{} (unreadable: {})".format(rel, exc))
            continue
        if current != outputs[rel]:
            stale.append(rel)
    return stale


def write_outputs(dest: Path, outputs: Dict[str, str]) -> List[Tuple[str, bool]]:
    results = []
    for rel in sorted(outputs):
        path = dest / rel
        try:
            current = path.read_text(encoding="utf-8")
        except (OSError, UnicodeDecodeError):
            current = None
        if current == outputs[rel]:
            results.append((rel, False))
            continue
        path.parent.mkdir(parents=True, exist_ok=True)
        with open(path, "w", encoding="utf-8", newline="\n") as handle:
            handle.write(outputs[rel])
        results.append((rel, True))
    return results


def main(argv: Optional[Sequence[str]] = None) -> int:
    parser = argparse.ArgumentParser(
        prog="build.py",
        description="Generate the eval dashboard, llms.txt, llms-full.txt and the README proof block.",
        epilog="Exit codes: 0 done or up to date, 1 stale outputs with --check, 2 bad input or usage.",
    )
    parser.add_argument("--check", action="store_true", help="write nothing; exit 1 if a committed output is stale")
    parser.add_argument("--root", type=Path, default=DEFAULT_ROOT, help="repository root (default: this checkout)")
    parser.add_argument(
        "--summary",
        action="append",
        type=Path,
        metavar="FILE",
        help="read this summary instead of searching packs/ and labs/ (repeatable; needs --out)",
    )
    parser.add_argument("--out", type=Path, metavar="DIR", help="write outputs under DIR, mirroring repository paths")
    args = parser.parse_args(argv)
    if args.check and (args.summary or args.out):
        parser.error("--check compares the committed outputs, so it can't take --summary or --out")
    if args.summary and not args.out:
        parser.error("--summary needs --out, so preview data never overwrites committed outputs")

    root = args.root.resolve()
    try:
        outputs, warnings = generate(root, args.summary)
    except InputError as exc:
        print("error: {}".format(exc), file=sys.stderr)
        return 2
    for warning in warnings:
        print("warning: {}".format(warning), file=sys.stderr)

    if args.check:
        stale = stale_outputs(root, outputs)
        if stale:
            for item in stale:
                print("stale: {}".format(item))
            print("{} out of date. Run: {}".format(_plural(len(stale), "generated file"), BUILD_CMD))
            return 1
        print("up to date: {}".format(_plural(len(outputs), "generated file")))
        return 0

    dest = args.out.resolve() if args.out else root
    for rel, changed in write_outputs(dest, outputs):
        print("{} {}".format("wrote" if changed else "unchanged", rel))
    return 0


if __name__ == "__main__":
    sys.exit(main())
